<body>
  <header class="app-header">
    <div class="header-content">
      <button class="back-button" type="button" aria-label="رجوع">‹</button>
      <h1>عنوان التوصيل</h1>
      <p class="subtitle">أدخل تفاصيل العنوان لتسهيل وصول طلبك</p>
    </div>
  </header>

  <main>
    <form class="card" id="addressForm" novalidate>
      <div class="success-message" id="successMessage" role="status">
        <span>✓</span>
        <span>تم حفظ عنوان التوصيل بنجاح</span>
      </div>

      <h2 class="section-title">معلومات العنوان</h2>

      <div class="field">
        <label for="building">المبنى أو الفيلا</label>
        <div class="input-wrap">
          <input id="building" name="building" type="text" placeholder="مثال: مبنى 12، فيلا 5" required>
          <span class="input-icon" aria-hidden="true">⌂</span>
        </div>
        <div class="field-error">يرجى إدخال المبنى أو الفيلا</div>
      </div>

      <div class="field">
        <label for="street">الشارع</label>
        <div class="input-wrap">
          <input id="street" name="street" type="text" placeholder="اسم الشارع" required>
          <span class="input-icon" aria-hidden="true">⌁</span>
        </div>
        <div class="field-error">يرجى إدخال اسم الشارع</div>
      </div>

      <div class="field">
        <label for="area">المنطقة</label>
        <div class="input-wrap">
          <input id="area" name="area" type="text" placeholder="اسم المنطقة" required>
          <span class="input-icon" aria-hidden="true">◎</span>
        </div>
        <div class="field-error">يرجى إدخال اسم المنطقة</div>
      </div>

      <div class="field">
        <label for="emirate">الإمارة</label>
        <select id="emirate" name="emirate" required>
          <option value="dubai" selected>دبي</option>
          <option value="abu-dhabi">أبوظبي</option>
          <option value="sharjah">الشارقة</option>
          <option value="ajman">عجمان</option>
          <option value="umm-al-quwain">أم القيوين</option>
          <option value="ras-al-khaimah">رأس الخيمة</option>
          <option value="fujairah">الفجيرة</option>
        </select>
      </div>

      <div class="field">
        <label for="makani">رقم-location <span class="optional">(اختياري)</span></label>
        <div class="input-wrap">
          <input id="makani" name="makani" type="text" inputmode="numeric" placeholder="أدخل رقم المبنى">
          <span class="input-icon" aria-hidden="true">#</span>
        </div>
      </div>

      <div class="field">
        <label for="phone">رقم الهاتف</label>
        <div class="phone-row">
          <select aria-label="رمز الدولة">
            <option value="+971">+971</option>
            <option value="+966">+966</option>
            <option value="+965">+965</option>
            <option value="+968">+968</option>
          </select>
          <input id="phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="050 123 4567" required>
        </div>
        <div class="field-error">يرجى إدخال رقم هاتف صحيح</div>
      </div>

      <button class="save-button" id="saveButton" type="submit">حفظ العنوان</button>
      <p class="privacy-note">سيتم استخدام هذا العنوان لتوصيل طلباتك فقط</p>
    </form>
  </main>

  <script>
    const form = document.getElementById('addressForm');
    const phone = document.getElementById('phone');
    const successMessage = document.getElementById('successMessage');
    const saveButton = document.getElementById('saveButton');

    form.addEventListener('submit', function (event) {
      event.preventDefault();
      let valid = true;

      form.querySelectorAll('[required]').forEach(function (element) {
        const field = element.closest('.field');
        const isPhone = element === phone;
        const phoneDigits = phone.value.replace(/\D/g, '');
        const isValid = isPhone
          ? phoneDigits.length >= 9
          : element.value.trim() !== '';

        field.classList.toggle('invalid', !isValid);
        if (!isValid) valid = false;
      });

      if (!valid) {
        successMessage.classList.remove('show');
        return;
      }

      saveButton.disabled = true;
      saveButton.textContent = 'جارٍ الحفظ...';

      setTimeout(function () {
        successMessage.classList.add('show');
        saveButton.textContent = 'تم حفظ العنوان';
        successMessage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }, 500);
    });

    form.querySelectorAll('input, select').forEach(function (element) {
      element.addEventListener('input', function () {
        element.closest('.field').classList.remove('invalid');
      });
    });
  </script>
</body>
</html>
